package store.model;
import java.util.*;
public final class Catalog{private final Map<String,Category> categories=new LinkedHashMap<>();private final Map<String,Product> products=new LinkedHashMap<>();public void addCategory(Category c){if(c==null||categories.putIfAbsent(c.id(),c)!=null)throw new IllegalArgumentException("Duplicate category");}public void addProduct(Product p){if(p==null||!categories.containsKey(p.category().id())||products.putIfAbsent(p.id(),p)!=null)throw new IllegalArgumentException("Invalid or duplicate product");}public Product product(String id){Product p=products.get(id);if(p==null)throw new IllegalArgumentException("Unknown product: "+id);return p;}public List<Product> searchByName(String text){return products.values().stream().filter(p->p.name().toLowerCase().contains(text.toLowerCase())).toList();}public List<Product> byCategory(String id){return products.values().stream().filter(p->p.category().id().equals(id)).toList();}public Collection<Product> products(){return Collections.unmodifiableCollection(products.values());}public int size(){return products.size();}}
